// Módulo 90300: Europa, dados. Contornos dos países europeus (Natural Earth 1:50m, domínio público, simplificados a
// ~0,01°, ilhéus abaixo de ~4 km² retirados; Rússia, Bielorrússia, Turquia e Cáucaso fora). Erro de cerca de 1 km junto
// às fronteiras: serve para saber de que país é um terreno e responder na língua certa, não para limites legais.
// Pedido do Nuno, 21/10/2026, 19h03: «prepara a Europa toda». Usado pelo m90301. Comprimido para não pesar no arranque:
// só é descomprimido quando alguém pergunta o país de um ponto.
if ( ! defined( 'ABSPATH' ) ) { exit; }
function tcd_eu_contornos() {
	static $d = null; if ( null !== $d ) { return $d; }
	$d = json_decode( (string) gzuncompress( base64_decode( tcd_eu_contornos_raw() ) ), true );
	return $d = is_array( $d ) ? $d : array();
}
function tcd_eu_contornos_raw() {
	return '';
}
